<?php
 namespace QQWorld\Braintree\Test\Unit\Gateway\Validator; use Braintree\Transaction; use QQWorld\Braintree\Gateway\Validator\PaymentNonceResponseValidator; use QQWorld\Payment\Gateway\Validator\ResultInterface; use QQWorld\Payment\Gateway\Validator\ResultInterfaceFactory; use QQWorld\Braintree\Gateway\Helper\SubjectReader; class PaymentNonceResponseValidatorTest extends \PHPUnit\Framework\TestCase { private $validator; private $resultInterfaceFactory; private $subjectReader; protected function setUp() { $this->resultInterfaceFactory = $this->getMockBuilder(ResultInterfaceFactory::class) ->disableOriginalConstructor() ->setMethods(['create']) ->getMock(); $this->subjectReader = $this->getMockBuilder(SubjectReader::class) ->disableOriginalConstructor() ->setMethods(['readResponseObject']) ->getMock(); $this->validator = new PaymentNonceResponseValidator( $this->resultInterfaceFactory, $this->subjectReader ); } public function testFailedValidate() { $obj = new \stdClass(); $obj->success = true; $subject = [ 'response' => [ 'object' => $obj ] ]; $this->subjectReader->expects(static::once()) ->method('readResponseObject') ->willReturn($obj); $result = $this->createMock(ResultInterface::class); $this->resultInterfaceFactory->expects(self::once()) ->method('create') ->with([ 'isValid' => false, 'failsDescription' => [ __('Payment method nonce can\'t be retrieved.') ] ]) ->willReturn($result); $actual = $this->validator->validate($subject); static::assertEquals($result, $actual); } public function testValidateSuccess() { $obj = new \stdClass(); $obj->success = true; $obj->paymentMethodNonce = new \stdClass(); $obj->paymentMethodNonce->nonce = 'fj2hd9239kd1kq9'; $subject = [ 'response' => [ 'object' => $obj ] ]; $this->subjectReader->expects(static::once()) ->method('readResponseObject') ->willReturn($obj); $result = $this->createMock(ResultInterface::class); $this->resultInterfaceFactory->expects(self::once()) ->method('create') ->with([ 'isValid' => true, 'failsDescription' => [] ]) ->willReturn($result); $actual = $this->validator->validate($subject); static::assertEquals($result, $actual); } } 